src='''def _candidates(grid, r, c):
    found = []
    for orientation in (0, 1):
        line = grid[r][:] if orientation == 0 else [grid[i][c] for i in range(len(grid))]
        pos = c if orientation == 0 else r
        left = 0
        while pos - left - 1 >= 0 and left < 8 and line[pos - left - 1] != 6:
            left += 1
        right = 0
        while pos + right + 1 < len(grid) and right < 8 and line[pos + right + 1] != 6:
            right += 1
        if left + right == 0:
            continue
        before = line[pos - left:pos]
        after = line[pos + 1:pos + 1 + right]
        for other_orientation in (0, 1):
            for index in range(len(grid)):
                other = grid[index][:] if other_orientation == 0 else [grid[i][index] for i in range(len(grid))]
                for candidate_pos in range(len(grid)):
                    if other[candidate_pos] == 6 or candidate_pos < left or candidate_pos + right >= len(grid):
                        continue
                    if other[candidate_pos - left:candidate_pos] == before and other[candidate_pos + 1:candidate_pos + 1 + right] == after:
                        found.append((left + right, other[candidate_pos]))
    return found

def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 6 and grid[c][r] != 6:
                out[r][c] = grid[c][r]
    for r in range(n):
        for c in range(r, n):
            if grid[r][c] != 6 or grid[c][r] != 6:
                continue
            evidence = _candidates(grid, r, c) + ([] if r == c else _candidates(grid, c, r))
            if evidence:
                best = max(score for score, _ in evidence)
                values = [value for score, value in evidence if score == best]
                value = max(set(values), key=values.count)
                out[r][c] = out[c][r] = value
    return out
